#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_alpha;
uniform float amzp_scalinesOpt;
uniform float amzp_scalinesOpta;
uniform float amzp_scalinesOptb;
uniform float amzp_bottomStaticOpt;
uniform float amzp_rgbOffsetOpt;
uniform float amzp_horzFuzzOpt;
uniform float amzp_seed;
uniform float amzp_ggg;
uniform float amzp_wave;
uniform float amzp_hardoff;
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
    float3 mod289(float3 x) {
      return x - floor(x * (1.0 / 289.0)) * 289.0;
    }
    float2 mod289(float2 x) {
      return x - floor(x * (1.0 / 289.0)) * 289.0;
    }
    float3 permute(float3 x) {
      return mod289(((x*34.0)+1.0)*x);
    }
    float snoise(float2 v)
      {
      const float4 C = float4(0.211324865405187,
                          0.366025403784439,
                         -0.577350269189626,
                          0.024390243902439);
      float2 i = floor(v + dot(v, C.yy) );
      float2 x0 = v - i + dot(i, C.xx);
      float2 i1;
      i1 = (x0.x > x0.y) ? float2(1.0, 0.0) : float2(0.0, 1.0);
      float4 x12 = x0.xyxy + C.xxzz;
      x12.xy -= i1;
      i = mod289(i);
      float3 p = permute( permute( i.y + float3(0.0, i1.y, 1.0 ))
      + i.x + float3(0.0, i1.x, 1.0 ));
      float3 m = max(0.5 - float3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
      m = m*m ;
      m = m*m ;
      float3 x = 2.0 * fract(p * C.www) - 1.0;
      float3 h = abs(x) - 0.5;
      float3 ox = floor(x + 0.5);
      float3 a0 = x - ox;
      m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
      float3 g;
      g.x = a0.x * x0.x + h.x * x0.y;
      g.yz = a0.yz * x12.xz + h.yz * x12.yw;
      return 130.0 * dot(m, g);
    }
    float staticV(float2 satriyaid) {
        float staticHeight = snoise(float2(9.0,1.0*1.2+3.0))*0.3+5.0;
        float staticAmount = snoise(float2(1.0,1.0*1.2-6.0))*0.1+0.3;
        float staticStrength = snoise(float2(-9.75,1.0*0.6-3.0))*2.0+2.0;
     return (1.0-step(snoise(float2(5.0*pow(1.0,2.0)+pow(satriyaid.x*7.0,1.2),pow((mod(1.0,100.0)+100.0)*satriyaid.y*0.3+3.0,staticHeight))),staticAmount))*staticStrength;
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float2 satriyaid = amzScreenNorm();
        satriyaid -= 0.5;
        satriyaid.x *= screen.zw.x/screen.zw.y;
        satriyaid /= 1.0;
        satriyaid.x /= screen.zw.x/screen.zw.y;
        satriyaid += 0.5;
        float rad = 0.0 * 0.0174533;
        float2 v = normalize(float2(cos(rad),-sin(rad)));
     float4 result;
     float jerkOffset = (1.0-step(snoise(float2(1.0*1.3,5.0)),0.8))*0.05;
     float fuzzOffset = snoise(float2(amzp_seed*15.0,satriyaid.y*80.0))*0.1;
     float largeFuzzOffset = snoise(float2(amzp_wave*1.0,satriyaid.y*25.0))*amzp_ggg;
        float vertMovementOn = (1.0-step(snoise(float2(1.0*0.2,8.0)),0.4))*1.0;
        float vertJerk = (1.0-step(snoise(float2(1.0*1.5,5.0)),0.6))*1.0;
        float vertJerk2 = (1.0-step(snoise(float2(1.0*5.5,5.0)),0.2))*1.0;
        float yOffset = abs(sin(1.0)*4.0)*vertMovementOn+vertJerk*vertJerk2*0.3;
        float y = mod(satriyaid.y+yOffset,amzp_hardoff);
     float xOffset = (fuzzOffset + largeFuzzOffset) * amzp_horzFuzzOpt;
        float staticVal = 0.0;
        for (float y = -1.0; y <= 1.0; y += 1.0) {
            float maxDist = 5.0/200.0;
            float dist = y/200.0;
         staticVal += staticV(float2(satriyaid.x,satriyaid.y+dist))*(maxDist-abs(dist))*1.7;
        }
        staticVal *= amzp_bottomStaticOpt;
     float red = amzTexture( 0, float2(satriyaid.x + xOffset -0.01*amzp_rgbOffsetOpt,y)).r+staticVal;
     float green = amzTexture( 0, float2(satriyaid.x + xOffset, y)).g+staticVal;
     float blue = amzTexture( 0, float2(satriyaid.x + xOffset +0.01*amzp_rgbOffsetOpt,y)).b+staticVal;
     float3 color = float3(red,green,blue);
     float scanline = sin(satriyaid.y*amzp_scalinesOptb)*amzp_scalinesOpta*amzp_scalinesOpt;
     color -= scanline;
     result = float4(color,1.0);
     float4 texColorOri = amzTexture(0,amzScreenNorm());
     float4 final = result * texColor.a;
     amzOutput = mix(texColor,final,amzp_alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
